/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Mul, Pow, Rational, Sym, fn, mul, pow, symbols, trigintegrate } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.integrals.trigonometry", () => {
  it("trigintegrate(sin(x)*cos(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigintegrate(mul(fn('cos', [x], { evaluate: false }), fn('sin', [x], { evaluate: false })), x))).toBe('sin(x)**2/2');
  });
  it("trigintegrate(sin(x)**2, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigintegrate(pow(fn('sin', [x], { evaluate: false }), Rational.of(2n, 1n, { gcd: 1n })), x))).toBe('x/2 - sin(x)*cos(x)/2');
  });
  it("trigintegrate(tan(x)*sec(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigintegrate(mul(fn('sec', [x], { evaluate: false }), fn('tan', [x], { evaluate: false })), x))).toBe('1/cos(x)');
  });
  it("trigintegrate(sin(x)*tan(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigintegrate(mul(fn('sin', [x], { evaluate: false }), fn('tan', [x], { evaluate: false })), x))).toBe('-log(sin(x) - 1)/2 + log(sin(x) + 1)/2 - sin(x)');
  });
});

